-- Source: reference/Final Fantasy Sound Sources (Detailed) - Final Fantasy X.csv
-- Section 1 part 1 of 3: tracks 1-30 (CSV rows 11-745). ~675 sample rows.
-- Per-sample shape (Sample # column present). Sample # resets per track
-- per the FFX/X-2/XI editor convention ("List by OST placement, then by
-- Sample #" — Rules.csv).
-- examples = numbered track title (e.g. "4. Tidus''s Theme").
-- Track headers and "(Arranged by ...)" rows skipped. Empty-description
-- placeholders (Prelude Sample 0, Hymn - Valefor Sample 0, The Sending) dropped.
-- Live Recording variants both with colon ("Live Recording: Yoko Mori") and
-- paren ("Live Recording (Masakazu Morita)") preserved verbatim in raw_source.
-- Verbatim transcription drift: "SOUND Canvas" vs "Sound Canvas" vs
-- "SOUND CANVAS" collapse via the NOCASE UNIQUE on products.name; "SC-88 Pro"
-- (spaced) vs "SC-88Pro" (no space) intentionally preserved as separate
-- products since whitespace differs.

INSERT OR IGNORE INTO products (manufacturer_id, name, type) VALUES
  ((SELECT id FROM manufacturers WHERE name = 'Roland'        COLLATE NOCASE), 'SOUND Canvas SC-8820',                'Hardware'),
  ((SELECT id FROM manufacturers WHERE name = 'Roland'        COLLATE NOCASE), 'SR-JV80-04 Vintage Synth',            'Hardware'),
  ((SELECT id FROM manufacturers WHERE name = 'Roland'        COLLATE NOCASE), 'SOUND Canvas SC-88 Pro',              'Hardware'),
  ((SELECT id FROM manufacturers WHERE name = 'Roland'        COLLATE NOCASE), 'SOUND Canvas SC-88Pro',               'Hardware'),
  ((SELECT id FROM manufacturers WHERE name = 'Spectrasonics' COLLATE NOCASE), 'Distorted Reality 2',                 'Sample Library'),
  ((SELECT id FROM manufacturers WHERE name = 'Kurzweil'      COLLATE NOCASE), 'Orchestral ROM',                      'Sample Library'),
  ((SELECT id FROM manufacturers WHERE name = 'Zero-G'        COLLATE NOCASE), 'Cuckooland Vol. 1 Unhinged',          'Sample Library'),
  ((SELECT id FROM manufacturers WHERE name = 'EastWest'      COLLATE NOCASE), 'Quantum Leap Guitar & Bass',          'Sample Library'),
  ((SELECT id FROM manufacturers WHERE name = 'Best Service'  COLLATE NOCASE), 'Advanced Orchestra',                  'Sample Library');

INSERT INTO games (title, platform, released, composers, composers_normalized, notes) VALUES
  ('Final Fantasy X',
   'PlayStation 2, PlayStation 3, PlayStation 4, PlayStation Vita, Nintendo Switch, Xbox One, PC',
   '2001-07-19',
   'Nobuo Uematsu, Masashi Hamauzu, Junya Nakano',
   'nobuo uematsu, masashi hamauzu, junya nakano',
   'Source: Final Fantasy Sound Sources (Detailed) - Final Fantasy X.csv (Section 1 - Original Soundtrack). CSV header notes "Over 100 samples are unknown for this game" and "This section is a work-in-progress." Per-track arrangers (Uematsu/Hamauzu/Nakano/Hirosato Noda/Shiro Hamaguchi) noted inline in the CSV are not captured at the row level; only the three primary composers are listed in this field. Section 1 ingestion split into 3 parts (this file: tracks 1-30).');

